554	// each showing its label and a status that updates independently — a spinner
555	// while in flight, ✓/✗ once terminal. On a non-terminal writer (pipes, tests)
556	// it degrades to one printed line per mirror as each reaches a terminal state.
557	type mirrorProgress struct {
558		w       io.Writer
559		tty     bool
560		labelW  int
561		mu      sync.Mutex
562		lines   []mirrorProgressLine
563		frame   int
564		painted bool
