634	// stop ends the animation and leaves the final state painted.
635	func (p *mirrorProgress) stop() {
636		if !p.tty {
637			return
638		}
639		close(p.done)
640		<-p.stopped
641		p.mu.Lock()
642		p.renderLocked()
643		p.mu.Unlock()
644	}
